  // src/api.ts
  async function requestJson(path, init) {
    const host5 = window.QwenPaw.host;
    const response = host5.fetch ? await host5.fetch(path, init) : await fetch(host5.getApiUrl(path), {
      ...init,
      headers: {
        ...init?.headers || {},
        ...host5.getApiToken() ? { Authorization: `Bearer ${host5.getApiToken()}` } : {}
      }
    });
    const content = await response.text();
    let payload = null;
    try {
      payload = content ? JSON.parse(content) : null;
    } catch {
      payload = null;
    }
    if (!response.ok) {
      let detail;
      if (payload && typeof payload === "object") {
        const p = payload;
        if (typeof p.detail === "string") detail = p.detail;
        else if (typeof p.message === "string") detail = p.message;
        else if (typeof p.error === "string") detail = p.error;
        else if (typeof p.errcode === "string")
          detail = `${p.errcode}: ${String(p.error ?? "")}`.trim();
      }
      throw new Error(
        typeof detail === "string" && detail ? `HTTP ${response.status}: ${detail}` : `HTTP ${response.status}`
      );
    }
    return payload;
  }
  function httpErrorStatus(e) {
    const m = e instanceof Error ? /^HTTP (\d{3})/.exec(e.message) : null;
    return m ? Number(m[1]) : null;
  }
  async function fetchApprovalList(agent) {
    const q = agent ? `?agent=${encodeURIComponent(agent)}` : "";
    return await requestJson(
      `/agentteams-proxy/approval/list${q}`
    );
  }
  async function setApprovalLevel(agent, level) {
    return await requestJson(`/agentteams-proxy/approval/set`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ agent, level })
    });
  }
  async function fetchWorkerApproval(name) {
    return await requestJson(
      `/agentteams-proxy/controller/api/v1/workers/${encodeURIComponent(
        name
      )}/approval`
    );
  }
  async function setWorkerApproval(name, level) {
    return await requestJson(
      `/agentteams-proxy/controller/api/v1/workers/${encodeURIComponent(
        name
      )}/approval`,
      {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ approval_level: level })
      }
    );
  }

